const state = { staff: null, permissions: [], products: [], categories: [], collections: [], edit: null, orderFilters: {}, importErrors: [], importFile: null }
const $ = selector => document.querySelector(selector)
const content = $('#page-content')
function addMfaRecoveryControls() { if (!state.staff?.roles?.includes('Super Admin')) return; document.querySelectorAll('[data-revoke-staff]').forEach(revoke => { if (revoke.parentElement.querySelector('[data-reset-mfa]')) return; const reset = document.createElement('button'); reset.type = 'button'; reset.className = 'danger small'; reset.dataset.resetMfa = revoke.dataset.revokeStaff; reset.textContent = 'Reset MFA'; reset.addEventListener('click', async () => { const reason = prompt('Enter the verified recovery reason (10–500 characters). This revokes every target session.'); if (!reason) return; if (!confirm('Reset this staff member’s MFA and revoke every one of their sessions?')) return; try { await api('/staff/' + reset.dataset.resetMfa + '/reset-mfa', { method: 'POST', body: JSON.stringify({ reason }) }); notify('MFA reset and target sessions revoked.'); staff() } catch (error) { notify(error.message, true) } }); revoke.insertAdjacentElement('afterend', reset) }) }
new MutationObserver(addMfaRecoveryControls).observe(content, { childList: true, subtree: true })
const pages = { '/dashboard': ['Overview', 'ERP control centre'], '/products': ['Products', 'Catalogue'], '/categories': ['Categories', 'Catalogue structure'], '/collections': ['Collections', 'Merchandising'], '/inventory': ['Inventory', 'Stock control'], '/inventory/imports': ['Stock imports', 'Inventory operations'], '/orders': ['Orders', 'Order operations'], '/staff': ['Staff access', 'Identity and permissions'], '/audit': ['Access audit', 'Security operations'] }
const escapeHtml = value => { const element = document.createElement('span'); element.textContent = String(value ?? ''); return element.innerHTML }
const rupiah = value => 'Rp ' + Number(value || 0).toLocaleString('id-ID')
const csrfToken = () => document.cookie.split('; ').find(value => value.startsWith('nilam_csrf='))?.split('=')[1] || ''
const applyPermissions = permissions => { state.permissions = permissions || []; document.querySelectorAll('[data-permission]').forEach(item => { item.hidden = !state.permissions.includes(item.dataset.permission) }) }
const renderStaffIdentity = () => { const node = $('#staff-identity'); if (node) { const staff = state.staff; node.textContent = staff ? (staff.firstName || staff.email) + (staff.roles?.length ? ' · ' + staff.roles.join(', ') : '') : 'Not signed in' } }

async function api(path, options = {}) {
  const response = await fetch('/api/admin' + path, { ...options, headers: { 'x-csrf-token': csrfToken(), 'content-type': 'application/json', ...(options.headers || {}) } })
  if (!response.ok) { const body = await response.json().catch(() => ({})); if (response.status === 401) { $('#app-view').hidden = true; $('#login-view').hidden = false; $('#login-error').textContent = 'Your staff session has expired. Please sign in again.' } if (response.status === 403) { content.innerHTML = '<div class="empty-state"><h2>Access denied</h2><p>You do not have permission for this ERP area. Contact an authorised administrator if you need access.</p></div>' } throw new Error(body.message || 'Request failed (' + response.status + ')') }
  return response.status === 204 ? null : response.json()
}
async function uploadMedia(path, form) {
  const response = await fetch('/api/admin' + path, { method: 'POST', headers: { 'x-csrf-token': csrfToken() }, body: new FormData(form) })
  if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.message || 'Upload failed (' + response.status + ')') }
  return response.json()
}
function notify(message, error = false) { const node = $('#toast'); node.textContent = message; node.className = 'toast' + (error ? ' toast-error' : ''); node.hidden = false; clearTimeout(notify.timer); notify.timer = setTimeout(() => { node.hidden = true }, 3500) }
function table(head, rows) { return '<div class="table-wrap"><table><thead><tr>' + head.map(item => '<th>' + item + '</th>').join('') + '</tr></thead><tbody>' + rows + '</tbody></table></div>' }
function activeNav(path) { document.querySelectorAll('[data-route]').forEach(item => item.classList.toggle('active', item.dataset.route === path)) }
function go(path) { const route = pages[path] ? path : '/dashboard'; if (location.pathname !== route) history.pushState({}, '', route); render() }
function loading() { content.innerHTML = '<div class="empty-state"><span class="spinner"></span><p>Loading workspace…</p></div>' }

async function dashboard() {
  const data = await api('/dashboard')
  const operations = data.operations24h || {}
  const cards = [['Net sales', rupiah(data.netSales)], ['Orders', data.orderCount], ['Active products', data.productCount], ['Low stock', data.lowStock], ['Pending import batches', data.pendingImportApply || 0], ['Failed logins · 24h', operations.failedLogins || 0], ['Rejected imports · 24h', operations.rejectedImports || 0], ['Shipment events · 24h', operations.shipmentEvents || 0]]
  content.innerHTML = '<section class="metrics">' + cards.map(card => '<article class="metric"><span>' + card[0] + '</span><strong>' + card[1] + '</strong><small>Current environment</small></article>').join('') + '</section><section class="dashboard-grid"><article class="panel"><p class="eyebrow">Quick actions</p><h2>Keep the catalogue moving</h2><p class="muted">Manage all product images as WebP files from the product editor.</p><div class="button-row"><button data-go="/products">Manage products</button><button class="secondary" data-go="/inventory">Adjust stock</button></div></article><article class="panel"><p class="eyebrow">Operational watch · 24h</p><h2>' + (operations.rejectedImports || 0) + ' rejected imports</h2><p class="muted">Review rejected imports and failed sign-ins in their operational views. Alert routing remains an approved deployment responsibility.</p><div class="button-row"><button class="secondary" data-go="/inventory/imports">Review imports</button><button class="secondary" data-go="/audit">Review access audit</button></div></article><article class="panel"><p class="eyebrow">Order queue</p><h2>' + data.pendingOrders + ' pending orders</h2><p class="muted">Use the order workspace to review paid orders and their approved fulfilment status.</p><div class="button-row"><button class="secondary" data-go="/orders">Review orders</button></div></article></section>'
}

function productRows(items) { return items.length ? items.map(item => '<tr><td><strong>' + escapeHtml(item.name) + '</strong><br><small>/' + escapeHtml(item.handle) + '</small></td><td>' + escapeHtml(item.category) + '</td><td><span class="status ' + String(item.status).toLowerCase() + '">' + escapeHtml(item.status) + '</span></td><td>' + item.stock + '</td><td><button class="secondary small" data-edit-product="' + item.id + '">Edit</button></td></tr>').join('') : '<tr><td colspan="5">No products found.</td></tr>' }
async function products() {
  state.products = await api('/products')
  content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Catalogue</p><h2>Products</h2><p class="muted">Manage product details, publishing status, and stock.</p></div><div class="product-actions"><input id="product-search" type="search" placeholder="Search products" /><button id="new-product" type="button">New product</button></div></div>' + table(['Product', 'Category', 'Status', 'Stock', ''], productRows(state.products)) + '</section>'
  $('#new-product').addEventListener('click', () => openProduct())
  $('#product-search').addEventListener('input', event => { const q = event.target.value.toLowerCase(); content.querySelector('tbody').innerHTML = productRows(state.products.filter(item => item.name.toLowerCase().includes(q) || item.handle.toLowerCase().includes(q))) })
}

function manager(kind, items) {
  const isCollection = kind === 'collections'; const singular = isCollection ? 'Collection' : 'Category'; const edit = state.edit || {}
  const description = isCollection ? '<label>Description<input name="description" value="' + escapeHtml(edit.description || '') + '" /></label>' : ''
  const rows = items.length ? items.map(item => '<tr><td><strong>' + escapeHtml(item.name) + '</strong></td><td>/' + escapeHtml(item.handle) + '</td>' + (isCollection ? '<td>' + escapeHtml(item.description || '—') + '</td>' : '') + '<td>' + item._count.products + '</td><td><button class="secondary small" data-edit-' + kind + '="' + item.id + '">Edit</button> <button class="danger small" data-delete-' + kind + '="' + item.id + '">Delete</button></td></tr>').join('') : '<tr><td colspan="5">No ' + kind + ' yet.</td></tr>'
  const headers = isCollection ? ['Collection', 'Handle', 'Description', 'Products', ''] : ['Category', 'Handle', 'Products', '']
  content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">' + (isCollection ? 'Merchandising' : 'Catalogue structure') + '</p><h2>' + singular + ' management</h2></div></div><form id="manager-form" class="inline-form"><label>Name<input name="name" required value="' + escapeHtml(edit.name || '') + '" /></label><label>Handle<input name="handle" required pattern="[a-z0-9-]+" value="' + escapeHtml(edit.handle || '') + '" /></label>' + description + '<div class="form-actions"><button>' + (edit.id ? 'Save changes' : 'Add ' + singular.toLowerCase()) + '</button>' + (edit.id ? '<button class="secondary" id="cancel-edit" type="button">Cancel</button>' : '') + '</div></form><p id="manager-error" class="error" role="alert"></p>' + table(headers, rows) + '</section>'
  $('#manager-form').addEventListener('submit', async event => { event.preventDefault(); try { await api('/' + kind + (edit.id ? '/' + edit.id : ''), { method: edit.id ? 'PATCH' : 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); state.edit = null; notify(edit.id ? 'Changes saved.' : singular + ' added.'); render() } catch (error) { $('#manager-error').textContent = error.message } })
  $('#cancel-edit')?.addEventListener('click', () => { state.edit = null; render() })
}
async function inventoryDetail(id, filters = {}) { const [detail, movements] = await Promise.all([api('/inventory/' + id + '/detail'), api('/inventory/' + id + '/movements?' + new URLSearchParams(filters))]); const movementRows = movements.length ? movements.map(item => '<tr><td>' + new Date(item.createdAt).toLocaleString() + '</td><td>' + (item.delta >= 0 ? '+' : '') + item.delta + '</td><td>' + item.previousQuantity + ' → ' + item.quantity + '</td><td>' + escapeHtml(item.reason) + '</td><td>' + escapeHtml(item.actor) + '</td></tr>').join('') : '<tr><td colspan="5">No movements match these filters.</td></tr>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">SKU inventory detail</p><h2>' + escapeHtml(detail.product.name) + ' · ' + escapeHtml(detail.variant.sku) + '</h2><p class="muted">Warehouse: MAIN. Available is equal to on hand until an approved reservation policy is enabled.</p></div><button id="back-inventory" class="secondary" type="button">Back to inventory</button></div><section class="metrics"><article class="metric"><span>On hand</span><strong>' + detail.inventory.quantity + '</strong></article><article class="metric"><span>Reserved</span><strong>' + detail.inventory.reservedQuantity + '</strong></article><article class="metric"><span>Available</span><strong>' + detail.inventory.availableQuantity + '</strong></article><article class="metric"><span>Low-stock threshold</span><strong>' + detail.inventory.lowStockThreshold + '</strong></article></section><form id="movement-filters" class="form-grid"><label>From<input name="from" type="date" value="' + escapeHtml(filters.from || '') + '" /></label><label>To<input name="to" type="date" value="' + escapeHtml(filters.to || '') + '" /></label><label>Reason contains<input name="reason" value="' + escapeHtml(filters.reason || '') + '" maxlength="160" /></label><div class="button-row"><button class="small">Filter movements</button></div></form>' + table(['When', 'Change', 'On hand', 'Reason / import source', 'Actor'], movementRows) + '</section>'; $('#back-inventory').addEventListener('click', inventory); $('#movement-filters').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); inventoryDetail(id, Object.fromEntries(Object.entries(values).filter(([, value]) => Boolean(value)))) .catch(error => notify(error.message, true)) }) }
async function inventory() { const items = await api('/inventory'); const rows = items.length ? items.map(item => '<tr><td><strong>' + escapeHtml(item.product) + '</strong>' + (item.lowStock ? '<br><small class="error">Low stock</small>' : '') + '</td><td>' + escapeHtml(item.variant) + '<br><small>' + escapeHtml(item.sku) + '</small></td><td><form class="stock-editor" data-variant="' + item.id + '"><label>On hand<input name="quantity" type="number" min="0" step="1" value="' + item.quantity + '" /></label><label>Low-stock at<input name="lowStockThreshold" type="number" min="0" step="1" value="' + item.lowStockThreshold + '" /></label><label>Reason<input name="reason" required maxlength="160" placeholder="Delivery received" /></label><button class="small">Save</button><button class="secondary small" type="button" data-history="' + item.id + '">History</button></form></td></tr>').join('') : '<tr><td colspan="3">No inventory records found.</td></tr>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Stock control</p><h2>Inventory</h2><p class="muted">Every saved change records a before/after movement and reason.</p></div></div>' + table(['Product', 'Variant / SKU', 'Stock control'], rows) + '</section>'; document.querySelectorAll('.stock-editor').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); try { const values = Object.fromEntries(new FormData(form)); await api('/inventory/' + form.dataset.variant, { method: 'PATCH', body: JSON.stringify({ quantity: Number(values.quantity), lowStockThreshold: Number(values.lowStockThreshold), reason: values.reason }) }); notify('Inventory updated.'); render() } catch (error) { notify(error.message, true) } })); document.querySelectorAll('[data-history]').forEach(button => button.addEventListener('click', () => inventoryDetail(button.dataset.history).catch(error => notify(error.message, true)))) }
const orderQuery = () => state.orderFilters
const formatAddress = address => address && typeof address === 'object' ? Object.values(address).filter(value => typeof value === 'string' || typeof value === 'number').join(', ') : 'No delivery address snapshot'
function nextFulfillmentStatus(status) { return status === 'UNFULFILLED' ? 'PROCESSING' : status === 'PROCESSING' ? 'SHIPPED' : status === 'SHIPPED' ? 'DELIVERED' : null }
async function showOrderDetail(id) { const order = await api('/orders/' + id); const next = nextFulfillmentStatus(order.fulfillmentStatus); const events = order.events.length ? order.events.map(event => '<li><strong>' + escapeHtml(event.event) + '</strong><br><small>' + new Date(event.createdAt).toLocaleString() + (event.actor ? ' · ' + escapeHtml(event.actor) : '') + '</small></li>').join('') : '<li class="muted">No timeline events yet.</li>'; const items = order.items.map(item => '<tr><td>' + escapeHtml(item.name) + '<br><small>' + escapeHtml(item.sku) + '</small></td><td>' + item.quantity + '</td><td>' + rupiah(item.price) + '</td></tr>').join(''); const shippingFields = next === 'SHIPPED' ? '<label>Approved carrier<input name="provider" required maxlength="60" placeholder="jne or jnt" /></label><label>Service<input name="service" required maxlength="100" placeholder="REG" /></label><label>Tracking number<input name="trackingNumber" required maxlength="160" /></label>' : '';
  const action = next ? '<form id="fulfillment-form" class="fulfillment-form" data-order="' + order.id + '" data-next="' + next + '"><p><strong>Next action: ' + next + '</strong></p>' + shippingFields + '<button>Mark ' + next.toLowerCase() + '</button></form>' : '<p class="muted">No further fulfilment action is available for this order.</p>';
  const notes = order.internalNotes?.length ? order.internalNotes.map(note => '<li><strong>' + escapeHtml(note.author) + '</strong><br>' + escapeHtml(note.body) + '<br><small>' + new Date(note.createdAt).toLocaleString() + '</small></li>').join('') : '<li class="muted">No internal notes yet.</li>'; const noteForm = state.permissions.includes('orders.manage') ? '<form id="order-note-form" class="note-form" data-order="' + order.id + '"><label>New internal note<textarea name="body" maxlength="2000" required></textarea></label><button>Add note</button></form>' : '<p class="muted">You have read-only access to internal notes.</p>';
  $('#order-detail').innerHTML = '<section class="panel order-detail"><div class="panel-heading"><div><p class="eyebrow">Order detail</p><h2>' + escapeHtml(order.orderNumber || order.id) + '</h2><p class="muted">' + escapeHtml(order.email) + ' · ' + rupiah(order.total) + '</p></div><button id="close-order-detail" class="secondary" type="button">Close</button></div><div class="order-facts"><p><strong>Payment</strong><br>' + escapeHtml(order.paymentStatus) + '</p><p><strong>Fulfilment</strong><br>' + escapeHtml(order.fulfillmentStatus) + '</p><p><strong>Shipment</strong><br>' + escapeHtml(order.shipment?.provider || 'Not assigned') + (order.shipment?.service ? ' · ' + escapeHtml(order.shipment.service) : '') + (order.shipment?.trackingNumber ? '<br>' + escapeHtml(order.shipment.trackingNumber) : '') + '</p><p><strong>Address snapshot</strong><br>' + escapeHtml(formatAddress(order.shippingAddress)) + '</p></div><h3>Items</h3>' + table(['Item', 'Qty', 'Unit price'], items) + '<h3>Fulfilment</h3>' + action + '<h3>Internal notes</h3><ol class="timeline notes">' + notes + '</ol>' + noteForm + '<h3>Timeline</h3><ol class="timeline">' + events + '</ol></section>';
  $('#close-order-detail').addEventListener('click', () => { $('#order-detail').innerHTML = '' })
  $('#fulfillment-form')?.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; const nextStatus = form.dataset.next; if (!confirm('Confirm fulfilment transition to ' + nextStatus + '?')) return; try { const values = Object.fromEntries(new FormData(form)); await api('/orders/' + form.dataset.order + '/fulfillment', { method: 'PATCH', body: JSON.stringify({ status: nextStatus, provider: values.provider, service: values.service, trackingNumber: values.trackingNumber }) }); notify('Fulfilment updated.'); await orders(); await showOrderDetail(form.dataset.order) } catch (error) { notify(error.message, true) } })
  $('#order-note-form')?.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; try { const values = Object.fromEntries(new FormData(form)); await api('/orders/' + form.dataset.order + '/notes', { method: 'POST', body: JSON.stringify({ body: values.body }) }); notify('Internal note added.'); await showOrderDetail(form.dataset.order) } catch (error) { notify(error.message, true) } })
}
async function orders() { const query = new URLSearchParams(Object.entries(orderQuery()).filter(([, value]) => value)); const data = await api('/orders?' + query); const rows = data.items.length ? data.items.map(item => '<tr><td><strong>' + escapeHtml(item.orderNumber || item.id.slice(-8).toUpperCase()) + '</strong><br><small>' + new Date(item.createdAt).toLocaleString() + '</small></td><td>' + escapeHtml(item.email) + '</td><td>' + escapeHtml(item.status) + '<br><small>' + escapeHtml(item.paymentStatus) + ' · ' + escapeHtml(item.fulfillmentStatus) + '</small></td><td>' + rupiah(item.total) + '</td><td><button class="secondary small" data-order-detail="' + item.id + '">View</button></td></tr>').join('') : '<tr><td colspan="5">No orders found.</td></tr>'; const pager = '<div class="button-row pager"><button class="secondary small" type="button" id="orders-previous"' + (data.pagination.page <= 1 ? ' disabled' : '') + '>Previous</button><span>Page ' + data.pagination.page + ' of ' + data.pagination.totalPages + '</span><button class="secondary small" type="button" id="orders-next"' + (data.pagination.page >= data.pagination.totalPages ? ' disabled' : '') + '>Next</button></div>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Order operations</p><h2>Orders</h2><p class="muted">Payment is provider-authoritative. Shipping actions are restricted to authorised staff.</p></div></div><form id="order-filters" class="order-filters"><label>Search<input name="q" type="search" value="' + escapeHtml(query.get('q') || '') + '" placeholder="Order, email, SKU, tracking" /></label><label>Payment<select name="paymentStatus"><option value="">All payments</option><option value="PENDING">Pending</option><option value="PAID">Paid</option><option value="FAILED">Failed</option><option value="REFUNDED">Refunded</option></select></label><label>Fulfilment<select name="fulfillmentStatus"><option value="">All fulfilment</option><option value="UNFULFILLED">Unfulfilled</option><option value="PROCESSING">Processing</option><option value="SHIPPED">Shipped</option><option value="DELIVERED">Delivered</option></select></label><label>From<input name="from" type="date" value="' + escapeHtml(query.get('from') || '') + '" /></label><label>To<input name="to" type="date" value="' + escapeHtml(query.get('to') || '') + '" /></label><button>Apply filters</button></form><p class="muted">' + data.pagination.total + ' matching order' + (data.pagination.total === 1 ? '' : 's') + ' · ' + rupiah(data.summary?.total || 0) + '.</p>' + table(['Order', 'Customer', 'Status', 'Total', ''], rows) + pager + '</section><div id="order-detail"></div>';
  $('#order-filters').paymentStatus.value = query.get('paymentStatus') || ''; $('#order-filters').fulfillmentStatus.value = query.get('fulfillmentStatus') || '';
  $('#order-filters').addEventListener('submit', event => { event.preventDefault(); state.orderFilters = { ...Object.fromEntries(new FormData(event.currentTarget).entries()), page: '1' }; orders() }); $('#orders-previous').addEventListener('click', () => { state.orderFilters = { ...state.orderFilters, page: String(Math.max(1, data.pagination.page - 1)) }; orders() }); $('#orders-next').addEventListener('click', () => { state.orderFilters = { ...state.orderFilters, page: String(Math.min(data.pagination.totalPages, data.pagination.page + 1)) }; orders() }); document.querySelectorAll('[data-order-detail]').forEach(button => button.addEventListener('click', () => showOrderDetail(button.dataset.orderDetail).catch(error => notify(error.message, true)))) }
async function staff() { const [staffMembers, roles] = await Promise.all([api('/staff'), api('/staff/roles')]); const roleOptions = roles.map(role => '<option value="' + role.id + '">' + escapeHtml(role.name) + '</option>').join(''); const rows = staffMembers.items.length ? staffMembers.items.map(member => '<tr><td><strong>' + escapeHtml(member.firstName ? member.firstName + ' ' + (member.lastName || '') : member.email) + '</strong><br><small>' + escapeHtml(member.email) + '</small></td><td><form class="role-editor" data-staff="' + member.id + '"><select name="roleIds" multiple aria-label="Roles for ' + escapeHtml(member.email) + '">' + roles.map(role => '<option value="' + role.id + '"' + (member.roles.some(assigned => assigned.id === role.id) ? ' selected' : '') + '>' + escapeHtml(role.name) + '</option>').join('') + '</select><button class="secondary small">Save roles</button></form></td><td><span class="status ' + (member.active ? '' : 'archived') + '">' + (member.active ? 'ACTIVE' : 'INACTIVE') + '</span></td><td><button class="secondary small" data-toggle-staff="' + member.id + '" data-active="' + member.active + '">' + (member.active ? 'Deactivate' : 'Activate') + '</button> <button class="secondary small" data-revoke-staff="' + member.id + '">Revoke sessions</button></td></tr>').join('') : '<tr><td colspan="4">No staff accounts found.</td></tr>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Identity and permissions</p><h2>Staff access</h2><p class="muted">Role changes, session revocations, and activation changes are audited. Invitations and recovery remain governed by the production identity policy.</p></div></div><p class="muted">Available roles: ' + roles.map(role => escapeHtml(role.name)).join(', ') + '</p>' + table(['Staff member', 'Roles', 'Status', 'Actions'], rows) + '</section>';
  content.insertAdjacentHTML('afterbegin', '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Onboard staff</p><h2>Invite a staff member</h2><p class="muted">A one-time password-setup link is delivered by the configured transactional-email provider.</p></div></div><form id="staff-invite" class="order-filters"><label>Email<input name="email" type="email" required /></label><label>First name<input name="firstName" maxlength="80" /></label><label>Last name<input name="lastName" maxlength="80" /></label><label>Roles<select name="roleIds" multiple required>' + roleOptions + '</select></label><button>Send invitation</button></form></section>'); $('#staff-invite').addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form)); const roleIds = Array.from(form.elements.roleIds.selectedOptions).map(option => option.value); if (!roleIds.length) { notify('Choose at least one role.', true); return } if (!confirm('Send a one-time ERP invitation to ' + values.email + '?')) return; try { await api('/staff/invitations', { method: 'POST', body: JSON.stringify({ email: values.email, firstName: values.firstName, lastName: values.lastName, roleIds }) }); notify('Invitation sent.'); staff() } catch (error) { notify(error.message, true) } }); document.querySelectorAll('.role-editor').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); const roleIds = Array.from(form.elements.roleIds.selectedOptions).map(option => option.value); if (!roleIds.length) { notify('Choose at least one role.', true); return } if (!confirm('Replace this staff member’s roles?')) return; try { await api('/staff/' + form.dataset.staff + '/roles', { method: 'PATCH', body: JSON.stringify({ roleIds }) }); notify('Roles updated.'); staff() } catch (error) { notify(error.message, true) } })); document.querySelectorAll('[data-toggle-staff]').forEach(button => button.addEventListener('click', async () => { const active = button.dataset.active !== 'true'; if (!confirm((active ? 'Activate' : 'Deactivate') + ' this staff account?')) return; try { await api('/staff/' + button.dataset.toggleStaff + '/active', { method: 'PATCH', body: JSON.stringify({ active }) }); notify('Staff account updated.'); staff() } catch (error) { notify(error.message, true) } })); document.querySelectorAll('[data-revoke-staff]').forEach(button => button.addEventListener('click', async () => { if (!confirm('Revoke every active session for this staff account?')) return; try { await api('/staff/' + button.dataset.revokeStaff + '/revoke-sessions', { method: 'POST', body: '{}' }); notify('Staff sessions revoked.'); staff() } catch (error) { notify(error.message, true) } })) }
async function audit() { const data = await api('/staff/access-events'); const rows = data.items.length ? data.items.map(item => '<tr><td>' + new Date(item.createdAt).toLocaleString() + '</td><td><strong>' + escapeHtml(item.event) + '</strong></td><td>' + escapeHtml(item.staff?.email || 'Unaffiliated') + '</td><td><small>' + escapeHtml(item.requestId || '—') + '</small></td></tr>').join('') : '<tr><td colspan="4">No access events match this filter.</td></tr>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Security operations</p><h2>Access audit</h2><p class="muted">Read-only staff access history. Event metadata is intentionally not rendered to avoid exposing sensitive values.</p></div></div><form id="audit-filter" class="order-filters"><label>Event name<input name="event" type="search" placeholder="e.g. staff.login" /></label><button>Filter events</button></form><p class="muted">' + data.pagination.total + ' event' + (data.pagination.total === 1 ? '' : 's') + '.</p>' + table(['When', 'Event', 'Staff account', 'Request ID'], rows) + '</section>'; $('#audit-filter').addEventListener('submit', async event => { event.preventDefault(); const value = new FormData(event.currentTarget).get('event'); try { const result = await api('/staff/access-events' + (value ? '?event=' + encodeURIComponent(String(value)) : '')); const body = content.querySelector('tbody'); body.innerHTML = result.items.length ? result.items.map(item => '<tr><td>' + new Date(item.createdAt).toLocaleString() + '</td><td><strong>' + escapeHtml(item.event) + '</strong></td><td>' + escapeHtml(item.staff?.email || 'Unaffiliated') + '</td><td><small>' + escapeHtml(item.requestId || '—') + '</small></td></tr>').join('') : '<tr><td colspan="4">No access events match this filter.</td></tr>' } catch (error) { notify(error.message, true) } }) }
function importStatus(item) { return '<span class="status import-' + String(item.status).toLowerCase() + '">' + escapeHtml(item.status) + '</span>' }
function csvTemplate() { return 'sku,quantity,warehouse,effective_at,source_reference,reason\nSKU-001,10,MAIN,2026-10-03T09:00:00+07:00,stocktake-2026-10-03,Stocktake correction\n' }
function downloadImportTemplate() { const blob = new Blob([csvTemplate()], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'nilam-stock-import-template.csv'; link.click(); URL.revokeObjectURL(url) }
function downloadImportErrors() { const csv = 'issue\n' + state.importErrors.map(error => '"' + String(error).replace(/"/g, '""') + '"').join('\n') + '\n'; const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'nilam-stock-import-errors.csv'; link.click(); URL.revokeObjectURL(url) }
async function showImportDetail(id) { const item = await api('/inventory/imports/' + id); const rowText = item.rows.map(row => 'Row ' + row.rowNumber + ' · ' + row.sku + ': ' + row.quantity + (row.error ? ' — ' + row.error : '')).join('\n'); const jobText = item.jobs?.length ? '\n\nJobs:\n' + item.jobs.map(job => job.operation + ' · ' + job.status + (job.error ? ' — ' + job.error : '')).join('\n') : ''; const canApply = item.status === 'VALIDATED'; const canRollback = item.status === 'APPLIED'; const action = canApply ? '\n\nQueue apply for this validated batch?' : canRollback ? '\n\nQueue rollback for this batch? This creates compensating movements and is limited to the configured window.' : '';
  if (!canApply && !canRollback) { alert(item.sourceReference + ' · ' + item.status + '\n\n' + (rowText || 'No rows') + jobText); return }
  if (!confirm(item.sourceReference + ' · ' + item.status + '\n\n' + (rowText || 'No rows') + jobText + action)) return
  if (canApply && !confirm('Confirm apply: this will set MAIN warehouse on-hand quantities to the validated values.')) return
  await api('/inventory/imports/' + id + '/' + (canApply ? 'apply' : 'rollback'), { method: 'POST', body: '{}' })
  notify(canApply ? 'Import apply job queued.' : 'Import rollback job queued.')
  setTimeout(render, 2500)
}
async function imports() { const data = await api('/inventory/imports'); const rows = data.items.length ? data.items.map(item => '<tr><td><strong>' + escapeHtml(item.sourceReference) + '</strong><br><small>' + new Date(item.createdAt).toLocaleString() + '</small></td><td>' + importStatus(item) + '</td><td>' + item.rowCount + '</td><td>' + escapeHtml(item.actor) + '</td><td><button class="secondary small" data-import-detail="' + item.id + '">Review</button></td></tr>').join('') : '<tr><td colspan="5">No import batches yet.</td></tr>'; content.innerHTML = '<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Inventory operations</p><h2>Stock imports</h2><p class="muted">Upload or drop a UTF-8 CSV for the MAIN warehouse. Preview validates it; a second confirmation applies only valid batches.</p></div><div class="button-row"><button id="download-import-template" class="secondary" type="button">Download template</button>' + (state.importErrors.length ? '<button id="download-import-errors" class="secondary" type="button">Download last error report</button>' : '') + '</div></div><form id="import-upload" class="import-upload"><label>CSV file<input name="file" type="file" accept=".csv,text/csv" required /></label><label>Source reference<input name="sourceReference" maxlength="160" required placeholder="e.g. stocktake-2026-10-03" /></label><button>Preview import</button><p id="import-drop-hint" class="muted">Drop one CSV file onto this form.</p></form><p class="muted import-help">Required columns: <code>sku, quantity, warehouse, effective_at, source_reference, reason</code>. Quantities are absolute on-hand values; CSV formulas, duplicate SKUs, unknown/archived SKUs, and non-MAIN rows are rejected.</p></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">Batch history</p><h2>Staged imports</h2></div></div>' + table(['Source', 'Status', 'Rows', 'Actor', ''], rows) + '</section>'; $('#download-import-template').addEventListener('click', downloadImportTemplate); $('#download-import-errors')?.addEventListener('click', downloadImportErrors); const uploadForm = $('#import-upload'); const setImportFile = file => { if (!file || !/\.csv$/i.test(file.name)) { notify('Choose or drop a CSV file.', true); return } state.importFile = file; $('#import-drop-hint').textContent = 'Selected: ' + file.name; if (!uploadForm.elements.sourceReference.value) uploadForm.elements.sourceReference.value = file.name }; uploadForm.elements.file.addEventListener('change', event => setImportFile(event.currentTarget.files[0])); ['dragenter', 'dragover'].forEach(name => uploadForm.addEventListener(name, event => { event.preventDefault(); uploadForm.classList.add('drag-over') })); ['dragleave', 'drop'].forEach(name => uploadForm.addEventListener(name, event => { event.preventDefault(); uploadForm.classList.remove('drag-over') })); uploadForm.addEventListener('drop', event => setImportFile(event.dataTransfer.files[0])); uploadForm.addEventListener('submit', async event => { event.preventDefault(); const form = event.currentTarget; const file = state.importFile || form.elements.file.files[0]; if (!file) { notify('Choose or drop a CSV file first.', true); return } if (file.size > 5 * 1024 * 1024) { notify('CSV files must be 5 MB or smaller.', true); return } try { const result = await api('/inventory/imports/preview', { method: 'POST', body: JSON.stringify({ csv: await file.text(), sourceReference: form.elements.sourceReference.value.trim() || file.name }) }); state.importFile = null; state.importErrors = result.errors || []; const errors = result.errors?.length ? '\n\nIssues:\n' + result.errors.join('\n') : ''; const summary = result.summary; alert('Preview ' + result.status + ': ' + summary.accepted + ' accepted, ' + summary.rejected + ' rejected, ' + summary.changed + ' changed, and ' + summary.unchanged + ' unchanged.' + errors + '\n\nReview the staged batch before applying it.'); notify(result.status === 'VALIDATED' ? 'Import validated. Review and apply it from batch history.' : 'Import rejected. Review the row errors in batch history.', result.status !== 'VALIDATED'); render() } catch (error) { notify(error.message, true) } }); document.querySelectorAll('[data-import-detail]').forEach(button => button.addEventListener('click', () => showImportDetail(button.dataset.importDetail).catch(error => notify(error.message, true)))) }

async function render() { const path = pages[location.pathname] ? location.pathname : '/dashboard'; if (path !== location.pathname) history.replaceState({}, '', path); const meta = pages[path]; $('#page-title').textContent = meta[0]; $('#page-eyebrow').textContent = meta[1]; activeNav(path); loading(); try { if (path === '/dashboard') await dashboard(); if (path === '/products') await products(); if (path === '/categories' || path === '/collections') manager(path.slice(1), await api(path)); if (path === '/inventory') await inventory(); if (path === '/inventory/imports') await imports(); if (path === '/orders') await orders(); if (path === '/staff') await staff(); if (path === '/audit') await audit() } catch (error) { content.innerHTML = '<div class="empty-state"><h2>Unable to load this page</h2><p>' + escapeHtml(error.message) + '</p><button id="retry-page" type="button">Try again</button></div>'; $('#retry-page').addEventListener('click', () => location.reload()) } }

async function refreshProductDialog(productId) { state.products = await api('/products'); await openProduct(state.products.find(item => item.id === productId)) }
function renderVariantManager(product) { const section = $('#variant-manager'); section.hidden = !product; if (!product) return; const rows = product.variants.map(variant => '<form class="variant-editor" data-variant="' + variant.id + '"><input name="name" value="' + escapeHtml(variant.name) + '" required /><input name="sku" value="' + escapeHtml(variant.sku) + '" required /><input name="price" type="number" min="0" step="1" value="' + variant.price + '" required /><span>' + (variant.inventory?.quantity || 0) + ' on hand</span><button class="secondary small">Save</button><button class="danger small" type="button" data-delete-variant="' + variant.id + '">Delete</button></form>').join(''); section.innerHTML = '<h3>Variants</h3><p class="muted">Stock is adjusted from Inventory to retain a movement history.</p><div class="variant-grid">' + rows + '</div><form id="new-variant" class="variant-editor"><input name="name" placeholder="Style / colour" required /><input name="sku" placeholder="SKU" required /><input name="price" type="number" min="0" step="1" placeholder="Price (IDR)" required /><input name="quantity" type="number" min="0" step="1" value="0" required /><button class="small">Add variant</button></form>'; section.querySelectorAll('.variant-editor[data-variant]').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); try { const values = Object.fromEntries(new FormData(form)); await api('/products/' + product.id + '/variants/' + form.dataset.variant, { method: 'PATCH', body: JSON.stringify(values) }); notify('Variant saved.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } })); section.querySelectorAll('[data-delete-variant]').forEach(button => button.addEventListener('click', async () => { if (!confirm('Delete this variant?')) return; try { await api('/products/' + product.id + '/variants/' + button.dataset.deleteVariant, { method: 'DELETE' }); notify('Variant deleted.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } })); $('#new-variant').addEventListener('submit', async event => { event.preventDefault(); try { await api('/products/' + product.id + '/variants', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); notify('Variant added.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } }) }
function renderMediaManager(product) { const section = $('#media-manager'); section.hidden = !product; if (!product) return; const media = product.media || []; const rows = media.length ? media.map(item => '<article class="media-item"><img src="' + escapeHtml(item.url) + '" alt="" /><form data-media="' + item.id + '"><label>Alt text<input name="alt" value="' + escapeHtml(item.alt) + '" required /></label><label>Position<input name="position" type="number" min="0" step="1" value="' + item.position + '" required /></label><button class="secondary small">Save</button><button class="danger small" type="button" data-delete-media="' + item.id + '">Delete</button></form></article>').join('') : '<p class="muted">No stored media yet. Legacy URL images must be replaced with a local upload before launch.</p>'; section.innerHTML = '<h3>Product media</h3><p class="muted">Uploads are converted to WebP and stored in the private bucket workflow. JPEG, PNG, or WebP source files only; maximum 10 MB.</p><div class="media-grid">' + rows + '</div><form id="media-upload" class="media-upload"><label>Image file<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required /></label><label>Alt text<input name="alt" required value="' + escapeHtml(product.name) + '" /></label><button class="small">Upload WebP</button></form>'; section.querySelectorAll('form[data-media]').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); try { await api('/products/' + product.id + '/media/' + form.dataset.media, { method: 'PATCH', body: JSON.stringify(Object.fromEntries(new FormData(form))) }); notify('Media saved.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } })); section.querySelectorAll('[data-delete-media]').forEach(button => button.addEventListener('click', async () => { if (!confirm('Delete this media object? This cannot be undone.')) return; try { await api('/products/' + product.id + '/media/' + button.dataset.deleteMedia, { method: 'DELETE' }); notify('Media deleted.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } })); $('#media-upload').addEventListener('submit', async event => { event.preventDefault(); try { await uploadMedia('/products/' + product.id + '/media', event.currentTarget); notify('WebP media uploaded.'); refreshProductDialog(product.id) } catch (error) { notify(error.message, true) } }) }
async function openProduct(product) { try { [state.categories, state.collections] = await Promise.all([api('/categories'), api('/collections')]); $('#product-form').reset(); $('#product-id').value = product?.id || ''; $('#product-name').value = product?.name || ''; $('#product-handle').value = product?.handle || ''; $('#product-description').value = product?.description || ''; $('#product-status').value = product?.status || 'DRAFT'; $('#product-category').innerHTML = state.categories.map(item => '<option value="' + item.id + '">' + escapeHtml(item.name) + '</option>').join(''); if (product) $('#product-category').value = state.categories.find(item => item.name === product.category)?.id || ''; const selectedCollections = new Set((product?.collections || []).map(item => item.collectionId)); $('#product-collections').innerHTML = state.collections.length ? state.collections.map(item => '<label class="check-option"><input type="checkbox" value="' + item.id + '"' + (selectedCollections.has(item.id) ? ' checked' : '') + ' /> ' + escapeHtml(item.name) + '</label>').join('') : '<small>Create a collection first to assign products.</small>'; $('#product-dialog-title').textContent = product ? 'Edit product' : 'New product'; document.querySelectorAll('.new-only').forEach(node => { node.hidden = Boolean(product); node.querySelectorAll('input').forEach(input => { input.required = !product && input.id !== 'product-image' }) }); renderVariantManager(product); renderMediaManager(product); $('#product-dialog').showModal() } catch (error) { notify(error.message, true) } }

document.addEventListener('click', event => { const target = event.target.closest('[data-route], [data-go], [data-edit-product], [data-edit-categories], [data-edit-collections], [data-delete-categories], [data-delete-collections]'); if (!target) return; if (target.dataset.route) { event.preventDefault(); go(target.dataset.route); return } if (target.dataset.go) { go(target.dataset.go); return } if (target.dataset.editProduct) { openProduct(state.products.find(item => item.id === target.dataset.editProduct)); return } const kind = target.dataset.editCategories || target.dataset.deleteCategories ? 'categories' : 'collections'; const id = target.dataset.editCategories || target.dataset.editCollections || target.dataset.deleteCategories || target.dataset.deleteCollections; if (target.dataset.deleteCategories || target.dataset.deleteCollections) { if (confirm('Delete this item?')) api('/' + kind + '/' + id, { method: 'DELETE' }).then(() => { notify('Deleted.'); render() }).catch(error => notify(error.message, true)) } else api('/' + kind).then(items => { state.edit = items.find(item => item.id === id); render() }) })
function enterWorkspace(body) { state.staff = body.staff; applyPermissions(body.permissions); renderStaffIdentity(); $('#login-view').hidden = true; $('#app-view').hidden = false; go('/dashboard') }
function renderMfaLogin(challengeToken) { $('#login-view').innerHTML = '<a class="login-brand" href="/">nilam<span>.</span></a><section class="login-card"><p class="eyebrow">ERP control centre</p><h1>Verify your sign-in</h1><p>Enter the current six-digit code from your authenticator app.</p><form id="mfa-login-form"><label>Authenticator code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus /></label><p id="mfa-login-error" class="error" role="alert"></p><button>Verify and open workspace</button><a class="identity-link" href="/">Back to sign in</a></form></section>'; $('#mfa-login-form').addEventListener('submit', async event => { event.preventDefault(); const error = $('#mfa-login-error'); try { const response = await fetch('/api/erp/auth/verify-mfa-login', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken() }, body: JSON.stringify({ challengeToken, code: new FormData(event.currentTarget).get('code') }) }); const body = await response.json(); if (!response.ok) throw new Error(body.message || 'Unable to verify code'); enterWorkspace(body) } catch (reason) { error.textContent = reason.message || 'Unable to verify code.' } }) }
$('#login-form')?.addEventListener('submit', async event => { event.preventDefault(); try { const response = await fetch('/api/erp/auth/login', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken() }, body: JSON.stringify({ email: $('#email-input').value, password: $('#password-input').value }) }); const body = await response.json(); if (!response.ok) throw new Error(body.message || 'Unable to sign in'); if (body.mfaRequired) { renderMfaLogin(body.challengeToken); return } enterWorkspace(body) } catch (error) { $('#login-error').textContent = error.message || 'Unable to sign in.' } })
$('#sign-out').addEventListener('click', async () => { try { await fetch('/api/erp/auth/logout', { method: 'POST', headers: { 'x-csrf-token': csrfToken() } }) } catch { /* Local session UI still needs to close if the API is unavailable. */ } sessionStorage.removeItem('nilam_admin_token'); state.staff = null; state.permissions = []; renderStaffIdentity(); $('#app-view').hidden = true; $('#login-view').hidden = false; history.replaceState({}, '', '/') })
$('#change-password').addEventListener('click', () => location.assign('/erp/change-password'))
$('#manage-mfa').addEventListener('click', () => location.assign('/erp/mfa'))
document.querySelectorAll('.close-dialog').forEach(button => button.addEventListener('click', () => $('#product-dialog').close()))
$('#product-form').addEventListener('submit', async event => { event.preventDefault(); const id = $('#product-id').value; try { const body = Object.fromEntries(new FormData(event.currentTarget)); body.collectionIds = Array.from(document.querySelectorAll('#product-collections input:checked')).map(input => input.value); await api('/products' + (id ? '/' + id : ''), { method: id ? 'PATCH' : 'POST', body: JSON.stringify(body) }); $('#product-dialog').close(); notify(id ? 'Product updated.' : 'Product created.'); go('/products') } catch (error) { $('#product-error').textContent = error.message } })
window.addEventListener('popstate', render)
async function restoreSession() { sessionStorage.removeItem('nilam_admin_token'); try { const response = await fetch('/api/erp/auth/session'); const body = await response.json(); if (body.staff) { state.staff = body.staff; applyPermissions(body.permissions); renderStaffIdentity(); $('#login-view').hidden = true; $('#app-view').hidden = false; render() } } catch { /* Keep the sign-in screen available when the API is unreachable. */ } }
function renderIdentityPage() { const path = location.pathname; const token = new URLSearchParams(location.search).get('token') || ''; const isInvite = path === '/erp/accept-invitation'; const isReset = path === '/erp/reset-password'; const isRequest = path === '/erp/request-password-reset'; if (!isInvite && !isReset && !isRequest) return false; const title = isInvite ? 'Set up ERP access' : isReset ? 'Choose a new password' : 'Reset your password'; const copy = isInvite ? 'Choose a password to activate your invited staff account.' : isReset ? 'Choose a new password for your staff account.' : 'Enter your staff email. If an active account matches it, recovery instructions will be sent.'; const form = isRequest ? '<label>Email<input name="email" type="email" autocomplete="email" required /></label>' : '<label>New password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required /></label><label>Confirm password<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="256" required /></label>'; $('#login-view').innerHTML = '<a class="login-brand" href="/">nilam<span>.</span></a><section class="login-card"><p class="eyebrow">ERP control centre</p><h1>' + title + '</h1><p>' + copy + '</p><form id="identity-form">' + form + '<p id="identity-error" class="error" role="alert"></p><button>' + (isRequest ? 'Send instructions' : 'Save password') + '</button><a class="identity-link" href="/">Back to sign in</a></form></section>'; $('#identity-form').addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); const error = $('#identity-error'); if (!isRequest && values.password !== values.confirmation) { error.textContent = 'Passwords do not match.'; return } try { const endpoint = isRequest ? '/api/erp/auth/request-password-reset' : isInvite ? '/api/erp/auth/accept-invitation' : '/api/erp/auth/reset-password'; const response = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken() }, body: JSON.stringify(isRequest ? { email: values.email } : { token, password: values.password }) }); const body = response.status === 204 ? {} : await response.json(); if (!response.ok) throw new Error(body.message || 'Unable to complete this request'); if (isRequest) { error.className = 'success'; error.textContent = body.message; return } location.assign('/dashboard') } catch (reason) { error.className = 'error'; error.textContent = reason.message || 'Unable to complete this request.' } }); return true }
function renderChangePasswordPage() { if (location.pathname !== '/erp/change-password') return false; $('#login-view').innerHTML = '<a class="login-brand" href="/dashboard">nilam<span>.</span></a><section class="login-card"><p class="eyebrow">ERP control centre</p><h1>Change password</h1><p>Use a new password between 12 and 256 characters. All existing staff sessions will be revoked.</p><form id="change-password-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required /></label><label>New password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required /></label><label>Confirm password<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="256" required /></label><p id="change-password-error" class="error" role="alert"></p><button>Save password</button><a class="identity-link" href="/dashboard">Back to ERP</a></form></section>'; $('#change-password-form').addEventListener('submit', async event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); const error = $('#change-password-error'); if (values.password !== values.confirmation) { error.textContent = 'Passwords do not match.'; return } try { const response = await fetch('/api/erp/auth/change-password', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken() }, body: JSON.stringify({ currentPassword: values.currentPassword, password: values.password }) }); if (!response.ok) { const body = await response.json(); throw new Error(body.message || 'Unable to change password') } location.assign('/dashboard') } catch (reason) { error.textContent = reason.message || 'Unable to change password.' } }); return true }
function renderMfaPage() { if (location.pathname !== '/erp/mfa') return false; $('#login-view').innerHTML = '<a class="login-brand" href="/dashboard">nilam<span>.</span></a><section class="login-card"><p class="eyebrow">ERP security</p><h1>Set up multi-factor authentication</h1><p id="mfa-copy">Preparing your authenticator setup…</p><form id="mfa-confirm-form" hidden><label>Authenticator code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required /></label><p id="mfa-setup-error" class="error" role="alert"></p><button>Enable MFA</button><a class="identity-link" href="/dashboard">Back to ERP</a></form></section>'; void (async () => { const copy = $('#mfa-copy'); const form = $('#mfa-confirm-form'); try { const response = await fetch('/api/erp/auth/mfa/setup', { method: 'POST', headers: { 'x-csrf-token': csrfToken() } }); const body = await response.json(); if (!response.ok) throw new Error(body.message || 'Unable to start MFA setup'); copy.innerHTML = 'Add this secret to a TOTP authenticator app, then enter its current code. Keep this secret private.<br><br><code>' + escapeHtml(body.secret) + '</code>'; form.hidden = false; form.addEventListener('submit', async event => { event.preventDefault(); const error = $('#mfa-setup-error'); try { const confirm = await fetch('/api/erp/auth/mfa/confirm', { method: 'POST', headers: { 'content-type': 'application/json', 'x-csrf-token': csrfToken() }, body: JSON.stringify({ code: new FormData(event.currentTarget).get('code') }) }); if (!confirm.ok) { const result = await confirm.json(); throw new Error(result.message || 'Unable to enable MFA') } location.assign('/dashboard') } catch (reason) { error.textContent = reason.message || 'Unable to enable MFA.' } }) } catch (reason) { copy.textContent = reason.message || 'Unable to start MFA setup.' } })(); return true }
